$(window).resize(function(){var n=$("footer").outerHeight();$("body").css("padding-bottom",n)});$(document).ready(function(){var n=$("footer").outerHeight();$("body").css("padding-bottom",n);$(window).scroll(function(){$(window).scrollTop()>200?$(".scrollup").removeClass("hidden"):$(".scrollup").addClass("hidden")});$(".scrollup").click(function(){return $("body,html").animate({scrollTop:0},600),!1});$(".block_learn_more").mouseover(function(){$(this).find(".background_blur").hide();$(this).find(".overlay").attr("style","background-color:transparent !important;")});$(".block_learn_more").mouseout(function(){$(this).find(".background_blur").show();$(this).find(".overlay").attr("style","background-color:rgba(87, 135, 147,0.6);")})});